  'ejercicio.ejDesc.estiramiento-de-dorsales': 'Rek je zijkanten door je armen omhoog en licht opzij te heffen.',
  'ejercicio.ejDesc.movilidad-cervical': 'Langzame nekbewegingen in alle richtingen om spanning los te maken.',
  'ejercicio.ejDesc.rotaciones-de-columna': 'Draai je wervelkolom zachtjes segment voor segment om hem te mobiliseren.',
  'ejercicio.ejDesc.postura-de-la-cobra': 'Til in buiklig met je handen je borst op en strek daarbij je rug.',
  'ejercicio.ejDesc.inclinacion-lateral-de-cuello':
    'Breng je oor richting je schouder om de zijkant van je nek te rekken.',
  'ejercicio.ejDesc.estiramiento-de-cuadriceps':
    'Breng staand je hiel naar je bil en houd je voet vast om je bovenbeen te rekken.',
  'ejercicio.ejDesc.estiramiento-de-gemelos':
    'Plaats je handen tegen de muur en rek je kuit met het achterste been gestrekt.',
  'ejercicio.ejDesc.estiramiento-de-hombros': 'Kruis een arm voor je borst en trek hem met de andere arm naar je toe.',
  'ejercicio.ejDesc.foam-roller': 'Rol je spieren over de foamroller om spanning na de training los te maken.',
  'ejercicio.ejDesc.estiramiento-de-triceps': 'Breng je elleboog achter je hoofd en duw zachtjes met je andere hand.',
  'ejercicio.ejDesc.estiramiento-de-flexores-de-cadera':
    'Duw in een uitvalspas je heup naar voren om de voorkant van je dijbeen te rekken.',
  'ejercicio.ejDesc.piernas-en-la-pared':
    'Ga liggen en leg je benen tegen de muur om te ontspannen en te laten afvloeien.',
  'ejercicio.ejDesc.savasana': 'Ontspan liggend op je rug je hele lichaam terwijl je langzaam ademt.',
  'ejercicio.ejDesc.postura-del-nino-apoyada': 'Kindhouding met ondersteuning om langer te ontspannen.',
  'ejercicio.ejDesc.respiracion-profunda': 'Adem langzaam en diep in en uit om je zenuwstelsel te kalmeren.',
  'ejercicio.ejDesc.mariposa-reclinada':
    'Ga liggen met je voetzolen tegen elkaar, laat je knieën zakken en ontspan je heupen.',
  'ejercicio.ejDesc.torsion-reclinada':
    'Ga liggen en laat je knieën zachtjes naar één kant zakken om je wervelkolom te draaien.',
  'ejercicio.ejDesc.liberacion-miofascial-con-pelota':
    'Rol een harde bal met gecontroleerde druk van je hiel naar je voorvoet.',
  'ejercicio.ejDesc.circulos-de-tobillo': 'Til één been op en beweeg je enkel in wijde cirkels in beide richtingen.',
  'ejercicio.ejDesc.recogida-de-toalla-con-dedos':
    'Probeer met alleen je tenen een handdoek op de grond samen te knijpen.',
  'ejercicio.ejDesc.estiramiento-de-dorsiflexion':
    'Buig voor de muur je voorste knie terwijl je hiel plat op de grond blijft om te rekken.',
  'ejercicio.ejDesc.elevacion-de-talones-unipodal':
    'Til op één voet staand langzaam je hiel en laat hem met excentrische controle weer zakken.',
  'ejercicio.ejDesc.flexion-y-extension-en-descarga':
    'Buig liggend je knie tot je hiel je bil raakt, en strek het weer zonder je voet op te tillen.',
  'ejercicio.ejDesc.estiramiento-dinamico-de-isquiotibiales':
    'Plaats een hiel voor je en buig je romp zachtjes naar voren met de knie gestrekt.',
