    'Om posesanimaties te maken, bouw je het lichaam met 3D-onderdelen op het tabblad Lichaam.',
  'room.cocina.desc': 'Voeding: maaltijden, macro\'s, water en je weekplan bijhouden.',
  'room.ejercicio.desc': 'Routines voor kracht, uithoudingsvermogen en flexibiliteit met doelen.',
  'room.recamara.desc': 'Houd je rust bij en schrijf in je persoonlijke herinneringsdagboek.',
  'room.descanso.desc': 'Je slaap als een nachthemel: rooster, wekker, score en nachtlogboek.',
  'room.anecdotario.desc': 'Jouw herinneringsdagboek: herinneringen met foto\'s en dagelijkse stemming.',
  'room.despacho.desc':
    'Financiën: budget met uitgaven en inkomsten (vast en variabel), doelen (financiële rekentools, sparen/beleggen, schulden) met simulators, en actuele markten.',
  'room.biblioteca.desc': 'Gespreksencyclopedie: AI-chats, wiki-artikelen en studiesessies.',
  'room.entretenimiento.desc': 'Archief van films, series, boeken en bordspellen.',
  'room.sala.desc': 'Plan reizen: route, uitgaven, checklist en verlanglijst.',
  'room.jardin.desc': 'Rust: begeleide meditaties, ademhaling en dankbaarheidsdagboek.',
  'room.garage.desc': 'Onderhoud van je voertuigen en hun beurten.',
  'room.diario.desc': 'Dagelijks nieuwsoverzicht, per categorie.',
  'room.hobbies.desc': 'Jouw hobby\'s en creatieve projecten.',
  'room.idiomas.desc':
    'Talen leren: AI-tutor, woordenschat met gespreide herhaling, leerplan per niveau en oefeningen.',
  'room.calendario.desc': 'Jouw kalender: gebeurtenissen en routines per dag, week en maand.',
  'room.caminos.desc': 'Leg racebanen, treinrails en achtbanen aan op de kaart.',
  'room.canchas.desc': 'Plaats voetbal-, tennis-, basketbal- en honkbalvelden op de kaart.',
  'room.huerto.desc': 'Maak percelen klaar, zaai gewassen, geef ze water en oogst in real time.',
  'room.granja.desc':
    'Fok kippen, varkens, geiten, schapen, koeien en paarden, en verbouw hun voedsel in dezelfde editor.',
  'room.ideas.desc':
    'Jouw ideeëndagboek en brainstorms, tien conceptkaart-formaten op een vrij canvas (mindmap, boom, tijdlijn, cyclus, piramide, venn…) en acht beslissingsdiagrammen (voor-en-tegen, krachtenveld, SWOT, Eisenhower, beslisboom, tier list, gewogen beslismatrix en Ishikawa), met de hand of met AI.',
  'room.metas.desc':
    'Wat je je hebt voorgenomen, uit het hele huis: de lijst met doelen met hun subdoelen en stappen, de plannen die de AI voor elk doel voorstelt (fasen met een datum die echte subdoelen worden) en de planning waarin alles zijn periode inneemt op de tijdlijn.',
  'room.computo.desc':
    'Computerkamer: een wetenschappelijke rekenmachine met je formuleboek eraan gekoppeld (wiskunde, natuurkunde en scheikunde inbegrepen en bewerkbaar) en acht modi — een grafische plotter met vier types (2D, polair, parametrisch en 3D-oppervlak), binair en hexadecimaal, matrices, stelsels van vergelijkingen, eenheden omrekenen, fooi en regel van drie; en spreadsheets die naar Excel en PDF exporteren.',
