  'chat.manual.abrir': 'Handleiding: wat je kunt vragen',
  'chat.manual.aviso.caminos':
    'Bouwopdrachten openen een editor op volledig scherm: de chat sluit tot je afsluit met ✕. Verzorgingsacties werken zonder de chat te verlaten.',
  'chat.manual.aviso.granja':
    'Bouwopdrachten openen een editor op volledig scherm: de chat sluit tot je afsluit met ✕. Verzorgingsacties werken zonder de chat te verlaten.',
  'chat.manual.aviso.huerto':
    'Bouwopdrachten openen een editor op volledig scherm: de chat sluit tot je afsluit met ✕. Verzorgingsacties werken zonder de chat te verlaten.',
